css:
.hta-sim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #f4f7f9;
    color: #1f2d3d;
    padding: 22px;
    border-radius: 14px;
    max-width: 1080px;
    margin: 0 auto;
    border: 1px solid #d8e2e8;
}

.hta-sim-container * {
    box-sizing: border-box;
}

.hta-sim-header {
    background: linear-gradient(135deg, #0d6e6e 0%, #11998e 60%, #1a8fb5 100%);
    color: #ffffff;
    padding: 22px 26px;
    border-radius: 12px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(13,110,110,0.25);
}

.hta-sim-header-status {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    opacity: 0.85;
    margin-bottom: 8px;
    font-weight: 600;
}

.hta-sim-header h1 {
    font-size: 1.85rem;
    margin: 0 0 6px 0;
    font-weight: 700;
    letter-spacing: -0.01em;
}

.hta-sim-subtitle {
    font-size: 0.95rem;
    opacity: 0.92;
}

.hta-sim-clock-row {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
    flex-wrap: wrap;
}

.hta-sim-clock-block {
    background: #ffffff;
    border: 1px solid #d8e2e8;
    border-radius: 10px;
    padding: 10px 16px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #0d6e6e;
    display: flex;
    align-items: center;
    gap: 6px;
}

.hta-sim-clock-block .hta-sim-tag {
    font-size: 0.7rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #6b8290;
    font-weight: 700;
}

.hta-sim-phase {
    background: #e3f4f1;
    color: #0d6e6e;
    border-color: #b6e2da;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.hta-sim-deadline {
    background: #fff4e5;
    color: #b86a00;
    border-color: #ffd9a0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.hta-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 20px;
}

.hta-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e0e8ed;
    border-radius: 12px;
    padding: 16px 18px;
    box-shadow: 0 2px 6px rgba(31,45,61,0.05);
    transition: box-shadow 0.2s ease;
}

.hta-sim-kpi-card:hover {
    box-shadow: 0 4px 12px rgba(31,45,61,0.1);
}

.hta-sim-kpi-label {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #6b8290;
    font-weight: 700;
    margin-bottom: 8px;
}

.hta-sim-kpi-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1;
    color: #1f2d3d;
    letter-spacing: -0.02em;
}

.hta-sim-kpi-sub {
    font-size: 0.74rem;
    color: #8b9aa6;
    margin-top: 8px;
}

.hta-sim-kpi-icer {
    border-left: 5px solid #1a8fb5;
}

.hta-sim-kpi-icer .hta-sim-kpi-value {
    color: #1a8fb5;
}

.hta-sim-kpi-icer.hta-sim-over .hta-sim-kpi-value {
    color: #d64545;
}

.hta-sim-kpi-icer.hta-sim-under .hta-sim-kpi-value {
    color: #1f9d6b;
}

.hta-sim-kpi-score {
    border-left: 5px solid #11998e;
}

.hta-sim-kpi-meter {
    height: 8px;
    background: #e6edf1;
    border-radius: 5px;
    overflow: hidden;
    margin-top: 10px;
}

.hta-sim-kpi-meter-fill {
    height: 100%;
    width: 0%;
    border-radius: 5px;
    background: linear-gradient(90deg, #11998e, #1a8fb5);
    transition: width 0.5s ease, background 0.4s ease;
}

.hta-sim-briefing {
    background: #ffffff;
    border: 1px solid #e0e8ed;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 20px;
    box-shadow: 0 2px 6px rgba(31,45,61,0.05);
}

.hta-sim-briefing-head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}

.hta-sim-briefing-tag {
    background: #0d6e6e;
    color: #ffffff;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 6px;
}

.hta-sim-briefing-title {
    font-size: 1.2rem;
    font-weight: 700;
    color: #1f2d3d;
}

.hta-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #3b4d5c;
}

.hta-sim-briefing-text strong {
    color: #0d6e6e;
}

.hta-sim-briefing-coach {
    margin-top: 16px;
    padding: 14px 16px;
    background: #f0f7fa;
    border-left: 4px solid #1a8fb5;
    border-radius: 8px;
    font-size: 0.92rem;
    line-height: 1.6;
    color: #2b3e4c;
    font-style: italic;
}

.hta-sim-coach-tag {
    display: inline-block;
    font-style: normal;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #1a8fb5;
    margin-right: 8px;
}

.hta-sim-controls {
    background: #ffffff;
    border: 1px solid #e0e8ed;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 20px;
    box-shadow: 0 2px 6px rgba(31,45,61,0.05);
}

.hta-sim-controls h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #0d6e6e;
    margin: 0 0 16px 0;
}

.hta-sim-decisions-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
}

.hta-sim-decision-block {
    display: flex;
    flex-direction: column;
}

.hta-sim-decision-label {
    font-size: 0.9rem;
    font-weight: 700;
    color: #1f2d3d;
    margin-bottom: 4px;
}

.hta-sim-decision-hint {
    font-size: 0.78rem;
    color: #7a8b97;
    margin-bottom: 8px;
    line-height: 1.45;
}

.hta-sim-decision-block select,
.hta-sim-decision-block input {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdd9e0;
    border-radius: 8px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2d3d;
    font-family: inherit;
}

.hta-sim-decision-block select {
    background-color: #ffffff;
    color: #1f2d3d;
    cursor: pointer;
}

.hta-sim-decision-block select option {
    background-color: #ffffff;
    color: #1f2d3d;
}

.hta-sim-decision-block select:focus,
.hta-sim-decision-block input:focus {
    outline: none;
    border-color: #1a8fb5;
    box-shadow: 0 0 0 3px rgba(26,143,181,0.15);
}

.hta-sim-decision-range-row {
    display: flex;
    align-items: center;
    gap: 12px;
}

.hta-sim-decision-range-row input[type="range"] {
    flex: 1;
    padding: 0;
    accent-color: #1a8fb5;
}

.hta-sim-decision-range-val {
    min-width: 92px;
    text-align: right;
    font-weight: 700;
    color: #0d6e6e;
    font-size: 0.95rem;
}

.hta-sim-actions {
    margin-top: 20px;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.hta-sim-submit-btn {
    background: linear-gradient(135deg, #0d6e6e, #11998e);
    border: none;
    color: #ffffff;
    font-weight: 700;
    padding: 12px 28px;
    border-radius: 9px;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    box-shadow: 0 3px 10px rgba(13,110,110,0.3);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.hta-sim-submit-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 5px 16px rgba(13,110,110,0.4);
    color: #ffffff;
}

.hta-sim-undo-btn {
    border-color: #cdd9e0;
    color: #6b8290;
}

.hta-sim-feedback {
    background: #fbfdff;
    border: 1px solid #cfe4ec;
    border-left: 5px solid #1a8fb5;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 20px;
}

.hta-sim-feedback-head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}

.hta-sim-feedback-tag {
    background: #1a8fb5;
    color: #ffffff;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 6px;
}

#feedbackTitle {
    font-size: 1.05rem;
    font-weight: 700;
    color: #1f2d3d;
}

.hta-sim-feedback-text {
    font-size: 0.94rem;
    line-height: 1.65;
    color: #3b4d5c;
}

.hta-sim-feedback-text strong {
    color: #0d6e6e;
}

.hta-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #e0e8ed;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 20px;
    box-shadow: 0 2px 6px rgba(31,45,61,0.05);
}

.hta-sim-chart-wrap h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #0d6e6e;
    margin: 0 0 16px 0;
}

.hta-sim-history {
    background: #ffffff;
    border: 1px solid #e0e8ed;
    border-radius: 12px;
    padding: 20px 22px;
    box-shadow: 0 2px 6px rgba(31,45,61,0.05);
}

.hta-sim-history h3 {
    font-size: 1.05rem;
    font-weight: 700;
    color: #0d6e6e;
    margin: 0 0 16px 0;
}

.hta-sim-history-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.86rem;
}

.hta-sim-history-table th {
    background: #0d6e6e;
    color: #ffffff;
    text-align: left;
    padding: 9px 12px;
    font-weight: 600;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.hta-sim-history-table td {
    padding: 9px 12px;
    border-bottom: 1px solid #eef3f6;
    color: #3b4d5c;
}

.hta-sim-history-table tr:nth-child(even) td {
    background: #f8fbfc;
}

@media (max-width: 768px) {
    .hta-sim-container {
        padding: 14px;
    }
    .hta-sim-header h1 {
        font-size: 1.45rem;
    }
    .hta-sim-kpi-grid {
        grid-template-columns: 1fr;
    }
    .hta-sim-decisions-grid {
        grid-template-columns: 1fr;
    }
    .hta-sim-kpi-value {
        font-size: 2.1rem;
    }
    .hta-sim-clock-row {
        flex-direction: column;
    }
    .hta-sim-actions {
        flex-direction: column;
        align-items: stretch;
    }
    .hta-sim-submit-btn {
        width: 100%;
    }
}


/* FIX v1.1.0 — completion / committee-verdict screen */
.wtd-completion { padding: 10px 6px; text-align: center; }
.wtd-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 8px; }
.wtd-completion-score { font-size: 20px; color: #0f172a; margin-bottom: 16px; }
.wtd-completion-score strong { color: #0f766e; }
.wtd-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.wtd-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 96px; }
.wtd-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.wtd-completion-metric strong { font-size: 16px; color: #0f172a; }
.wtd-completion-verdict { max-width: 680px; margin: 0 auto; text-align: left; padding: 12px 16px; background: #f8fafc; border-left: 3px solid #0f766e; border-radius: 4px; color: #1e293b; font-size: 14px; line-height: 1.5; }

