(function() {
    'use strict';

    class WorthTheDeviceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Worth the Device';
            this.version = '1.1.0';

            // ---- Fixed dossier / hospital constants (from the NUMBERS REFERENCE CARD) ----
            this.C = {
                devicePrice: 22000,        // € per patient
                comparatorCost: 4000,      // € per patient, standard care add-on
                hospEligible: 150,         // advanced HF patients/yr at San Gerardo
                regionEligible: 1400,      // regional eligible pool (precedent effect)
                envelope: 2400000,         // uncommitted devices budget (€)
                regionAbsorbable: 12000000,// € the region can absorb before displacing care
                trialQaly: 0.6,            // sponsor-claimed QALY gain per patient
                pessimMult: 0.5,           // pessimistic case = half the trial benefit
                subgroupShare: 0.45,       // advanced sub-group as fraction of eligible pool
                subgroupQalyBoost: 1.35,   // value concentrates in the advanced sub-group
                moderateQalyMult: 0.55     // moderate-risk patients capture far less value
            };

            // ---- Round definitions ----
            this.ROUNDS = [
                {
                    phaseKey: 'phase_r1',
                    deadlineKey: 'deadline_r1',
                    tagKey: 'r1_tag',
                    titleKey: 'r1_title',
                    briefKey: 'r1_brief',
                    coachKey: 'r1_coach',
                    decisions: [
                        { id: 'wtp', type: 'select', labelKey: 'd_wtp_label', hintKey: 'd_wtp_hint', options: [
                            { value: '25000', labelKey: 'd_wtp_25' },
                            { value: '34000', labelKey: 'd_wtp_34' },
                            { value: '40000', labelKey: 'd_wtp_40' },
                            { value: '50000', labelKey: 'd_wtp_50' }
                        ]},
                        { id: 'evidence', type: 'select', labelKey: 'd_evidence_label', hintKey: 'd_evidence_hint', options: [
                            { value: 'sponsor',   labelKey: 'd_evidence_sponsor' },
                            { value: 'independent', labelKey: 'd_evidence_independent' },
                            { value: 'longterm',  labelKey: 'd_evidence_longterm' }
                        ]},
                        { id: 'qalycase', type: 'select', labelKey: 'd_qalycase_label', hintKey: 'd_qalycase_hint', options: [
                            { value: 'face',   labelKey: 'd_qalycase_face' },
                            { value: 'pessim', labelKey: 'd_qalycase_pessim' },
                            { value: 'range',  labelKey: 'd_qalycase_range' }
                        ]}
                    ]
                },
                {
                    phaseKey: 'phase_r2',
                    deadlineKey: 'deadline_r2',
                    tagKey: 'r2_tag',
                    titleKey: 'r2_title',
                    briefKey: 'r2_brief',
                    coachKey: 'r2_coach',
                    decisions: [
                        { id: 'subgroup', type: 'select', labelKey: 'd_subgroup_label', hintKey: 'd_subgroup_hint', options: [
                            { value: 'advanced', labelKey: 'd_subgroup_advanced' },
                            { value: 'broad',    labelKey: 'd_subgroup_broad' },
                            { value: 'all',      labelKey: 'd_subgroup_all' }
                        ]},
                        { id: 'uptake', type: 'range', labelKey: 'd_uptake_label', hintKey: 'd_uptake_hint',
                          min: 20, max: 100, step: 5, def: 100, fmt: 'pct' },
                        { id: 'scope', type: 'select', labelKey: 'd_scope_label', hintKey: 'd_scope_hint', options: [
                            { value: 'hospital', labelKey: 'd_scope_hospital' },
                            { value: 'regional', labelKey: 'd_scope_regional' }
                        ]}
                    ]
                },
                {
                    phaseKey: 'phase_r3',
                    deadlineKey: 'deadline_r3',
                    tagKey: 'r3_tag',
                    titleKey: 'r3_title',
                    briefKey: 'r3_brief',
                    coachKey: 'r3_coach',
                    decisions: [
                        { id: 'recommendation', type: 'select', labelKey: 'd_rec_label', hintKey: 'd_rec_hint', options: [
                            { value: 'adopt',      labelKey: 'd_rec_adopt' },
                            { value: 'restrict',   labelKey: 'd_rec_restrict' },
                            { value: 'managed',    labelKey: 'd_rec_managed' },
                            { value: 'reject',     labelKey: 'd_rec_reject' }
                        ]},
                        { id: 'tier', type: 'select', labelKey: 'd_tier_label', hintKey: 'd_tier_hint', options: [
                            { value: 'full',       labelKey: 'd_tier_full' },
                            { value: 'capped',     labelKey: 'd_tier_capped' },
                            { value: 'outcomes',   labelKey: 'd_tier_outcomes' },
                            { value: 'copay',      labelKey: 'd_tier_copay' }
                        ]},
                        { id: 'volcap', type: 'range', labelKey: 'd_volcap_label', hintKey: 'd_volcap_hint',
                          min: 30, max: 150, step: 10, def: 150, fmt: 'patients' }
                    ]
                },
                {
                    phaseKey: 'phase_r4',
                    deadlineKey: 'deadline_r4',
                    tagKey: 'r4_tag',
                    titleKey: 'r4_title',
                    briefKey: 'r4_brief',
                    coachKey: 'r4_coach',
                    decisions: [
                        { id: 'chief', type: 'select', labelKey: 'd_chief_label', hintKey: 'd_chief_hint', options: [
                            { value: 'hold',     labelKey: 'd_chief_hold' },
                            { value: 'retier',   labelKey: 'd_chief_retier' },
                            { value: 'cave',     labelKey: 'd_chief_cave' }
                        ]},
                        { id: 'discount', type: 'select', labelKey: 'd_discount_label', hintKey: 'd_discount_hint', options: [
                            { value: 'reject',   labelKey: 'd_discount_reject' },
                            { value: 'price',    labelKey: 'd_discount_price' },
                            { value: 'outcomes', labelKey: 'd_discount_outcomes' }
                        ]},
                        { id: 'equity', type: 'select', labelKey: 'd_equity_label', hintKey: 'd_equity_hint', options: [
                            { value: 'hold',     labelKey: 'd_equity_hold' },
                            { value: 'ced',      labelKey: 'd_equity_ced' },
                            { value: 'open',     labelKey: 'd_equity_open' }
                        ]}
                    ]
                }
            ];
        }

        // ===================== STATE =====================
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    // realized model state, persisted across rounds
                    wtp: 34000,
                    realizedQaly: this.C.trialQaly,
                    icer: 34000,
                    hospBudget: 0,
                    regBudget: 0,
                    qalysGained: 0,
                    accessPct: 0,
                    // four sub-scores (0-100)
                    valueScore: 50,
                    affordScore: 50,
                    evidenceScore: 50,
                    governScore: 50,
                    defensibility: 50,
                    // chart histories
                    icerHistory: [],
                    regBudgetHistory: [],
                    defensHistory: [],
                    wtpHistory: [],
                    decisionsLog: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        _clamp(v) {
            if (v < 0) return 0;
            if (v > 100) return 100;
            return v;
        }

        _fmtMoney(v) {
            // returns € with thousands separators, no decimals
            var n = Math.round(v);
            var neg = n < 0;
            n = Math.abs(n);
            var s = String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
            return (neg ? '-€' : '€') + s;
        }

        _fmtM(v) {
            return '€' + (Math.round(v / 100000) / 10).toFixed(1) + 'M';
        }

        // ===================== BRIEFING =====================
        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var phaseEl = document.getElementById('phaseLabel');
            if (phaseEl) phaseEl.textContent = t(round.phaseKey);

            var deadlineEl = document.getElementById('deadlineLabel');
            if (deadlineEl) deadlineEl.textContent = t(round.deadlineKey);

            var tagEl = document.getElementById('briefingTag');
            if (tagEl) tagEl.textContent = t(round.tagKey);

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefKey);

            var coachEl = document.getElementById('coachVoice');
            if (coachEl) coachEl.innerHTML = t(round.coachKey);

            this._renderDecisions(state, round, t);
        }

        _renderDecisions(state, round, t) {
            var container = document.getElementById('decisionsContainer');
            if (!container) return;
            var html = '';
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                html += '<div class="hta-sim-decision-block">';
                html += '<label class="hta-sim-decision-label" for="' + d.id + '">' + t(d.labelKey) + '</label>';
                if (d.hintKey) html += '<div class="hta-sim-decision-hint">' + t(d.hintKey) + '</div>';
                if (d.type === 'range') {
                    var cur = (state.decisions && typeof state.decisions[d.id] !== 'undefined') ? state.decisions[d.id] : d.def;
                    html += '<div class="hta-sim-decision-range-row">';
                    html += '<input type="range" id="' + d.id + '" min="' + d.min + '" max="' + d.max + '" step="' + d.step + '" value="' + cur + '">';
                    html += '<span class="hta-sim-decision-range-val" id="' + d.id + 'Val">' + this._fmtRange(d, cur, t) + '</span>';
                    html += '</div>';
                } else {
                    html += '<select id="' + d.id + '" name="' + d.id + '">';
                    for (var j = 0; j < d.options.length; j++) {
                        var o = d.options[j];
                        var sel = (state.decisions && state.decisions[d.id] === o.value) ? ' selected' : '';
                        html += '<option value="' + o.value + '"' + sel + '>' + t(o.labelKey) + '</option>';
                    }
                    html += '</select>';
                }
                html += '</div>';
            }
            container.innerHTML = html;

            // wire range readouts
            var self = this;
            for (var k = 0; k < round.decisions.length; k++) {
                var dd = round.decisions[k];
                if (dd.type === 'range') {
                    (function(decDef) {
                        var el = document.getElementById(decDef.id);
                        var val = document.getElementById(decDef.id + 'Val');
                        if (el && val) {
                            el.addEventListener('input', function() {
                                val.textContent = self._fmtRange(decDef, el.value, t);
                            });
                        }
                    })(dd);
                }
            }
        }

        _fmtRange(d, v, t) {
            if (d.fmt === 'pct') return v + '%';
            if (d.fmt === 'patients') return v + ' ' + t('unit_patients');
            return String(v);
        }

        // ===================== VALIDATE =====================
        validateDecisions(decisions) {
            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var collected = {};
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                var el = document.getElementById(d.id);
                if (!el) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('decision_missing'), 'warning');
                    return false;
                }
                if (d.type === 'range') {
                    var num = parseFloat(el.value);
                    if (!Number.isFinite(num)) {
                        window.mySimulation.uiManager.showNotification(window.mySimulation.t('decision_required'), 'warning');
                        return false;
                    }
                    collected[d.id] = num;
                } else {
                    if (!el.value) {
                        window.mySimulation.uiManager.showNotification(window.mySimulation.t('decision_required'), 'warning');
                        return false;
                    }
                    collected[d.id] = el.value;
                }
            }
            for (var key in collected) decisions[key] = collected[key];
            decisions._roundIndex = idx;
            return true;
        }

        // ===================== CORE HTA MODEL =====================
        // Pure helper: compute the realized QALY per patient from evidence + qaly-case + subgroup choices.
        _realizedQalyPerPatient(ds) {
            var q = this.C.trialQaly;
            // pessimistic / range cases discount the headline benefit
            if (ds.qalycase === 'pessim') q = q * this.C.pessimMult;          // 0.30
            else if (ds.qalycase === 'range') q = q * 0.78;                   // mid-range ~0.47
            // independent / long-term evidence demands shrink optimistic bias modestly but realistically
            if (ds.evidence === 'independent') q = q * 0.95;
            else if (ds.evidence === 'longterm') q = q * 0.90;
            // sub-group targeting concentrates value
            if (ds.subgroup === 'advanced') q = q * this.C.subgroupQalyBoost;        // value-rich
            else if (ds.subgroup === 'broad') q = q * 1.0;
            else if (ds.subgroup === 'all') q = q * this.C.moderateQalyMult;         // diluted
            return q;
        }

        // Pure helper: incremental cost per patient given the reimbursement tier / discount.
        _incrementalCostPerPatient(ds) {
            var price = this.C.devicePrice;
            // confidential discount mechanisms reduce effective price
            if (ds.discount === 'price') price = price * 0.85;             // 15% price-volume discount
            else if (ds.discount === 'outcomes') price = price * 0.80;     // outcomes-based effective price
            // reimbursement tier effect on effective net cost to the payer
            if (ds.tier === 'outcomes') price = price * 0.90;              // rebate on non-responders
            else if (ds.tier === 'copay') price = price * 0.95;            // patient co-payment offsets
            return (price - this.C.comparatorCost);
        }

        // Pure helper: number of treated patients (hospital) given subgroup + uptake + volume cap + recommendation.
        _treatedPatients(ds) {
            var pool = this.C.hospEligible;
            // eligibility sub-group
            if (ds.subgroup === 'advanced') pool = Math.round(pool * this.C.subgroupShare); // ~68
            else if (ds.subgroup === 'broad') pool = Math.round(pool * 0.75);               // ~113
            // recommendation gate
            if (ds.recommendation === 'reject') return 0;
            if (ds.recommendation === 'restrict') pool = Math.round(pool * this.C.subgroupShare / Math.max(0.0001, (ds.subgroup === 'advanced' ? this.C.subgroupShare : 1)));
            // uptake fraction
            var uptake = (typeof ds.uptake === 'number') ? ds.uptake : 100;
            var treated = pool * (uptake / 100);
            // managed access caps to a pilot cohort while data matures
            if (ds.recommendation === 'managed') treated = Math.min(treated, pool * 0.5);
            // volume cap (capped tier) hard-limits volume
            if (ds.tier === 'capped' && typeof ds.volcap === 'number') treated = Math.min(treated, ds.volcap);
            return Math.max(0, Math.round(treated));
        }

        calculateResults(state) {
            var idx = state.decisions._roundIndex;
            if (typeof idx !== 'number') idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);
            var ds = state.decisions;
            var C = this.C;

            // ---- WTP threshold (set R1, persists) ----
            if (typeof ds.wtp !== 'undefined') state.domainState.wtp = parseFloat(ds.wtp);
            var wtp = state.domainState.wtp || 34000;

            // ---- Realized QALY per patient ----
            var qPer = this._realizedQalyPerPatient(ds);
            state.domainState.realizedQaly = qPer;

            // ---- Incremental cost & ICER ----
            var incCost = this._incrementalCostPerPatient(ds);
            var icer = qPer > 0 ? Math.round(incCost / qPer) : 999999;
            state.domainState.icer = icer;

            // ---- Treated patients, budget impact, QALYs, access ----
            var treated = this._treatedPatients(ds);
            var fullPrice = C.devicePrice;
            if (ds.discount === 'price') fullPrice = fullPrice * 0.85;
            else if (ds.discount === 'outcomes') fullPrice = fullPrice * 0.80;
            if (ds.tier === 'outcomes') fullPrice = fullPrice * 0.90;
            else if (ds.tier === 'copay') fullPrice = fullPrice * 0.95;

            var hospBudget = treated * fullPrice;
            // regional precedent multiplier (the eligible pool scales ~9.3x)
            var regionScale = C.regionEligible / C.hospEligible;
            var regBudget = hospBudget * regionScale;
            var qalysGained = treated * qPer;
            // access coverage relative to the FULL hospital eligible pool
            var accessPct = Math.round((treated / C.hospEligible) * 100);

            state.domainState.hospBudget = hospBudget;
            state.domainState.regBudget = regBudget;
            state.domainState.qalysGained = qalysGained;
            state.domainState.accessPct = accessPct;

            // ================= SCORING (4 sub-scores) =================
            // VALUE: ICER vs WTP. Best when ICER comfortably under threshold AND real value captured.
            var valueScore;
            if (treated === 0) {
                valueScore = 35; // rejecting forfeits all value
            } else {
                var ratio = icer / wtp;
                if (ratio <= 0.75) valueScore = 92;
                else if (ratio <= 1.0) valueScore = 78;
                else if (ratio <= 1.3) valueScore = 50;
                else valueScore = 22;
                // reward targeting the value-rich sub-group
                if (ds.subgroup === 'advanced') valueScore += 6;
                else if (ds.subgroup === 'all') valueScore -= 8;
            }

            // AFFORDABILITY: regional budget impact vs absorbable ceiling.
            var burden = regBudget / C.regionAbsorbable;
            var affordScore;
            if (treated === 0) {
                affordScore = 70; // nothing spent, but real benefit left on the table
            } else {
                if (burden <= 0.7) affordScore = 90;
                else if (burden <= 1.0) affordScore = 68;
                else if (burden <= 1.6) affordScore = 40;
                else affordScore = 18;
                // a toothless full tier with no volume control is penalised
                if (ds.tier === 'full' && burden > 0.6) affordScore -= 12;
                if (ds.tier === 'capped' || ds.tier === 'outcomes') affordScore += 6;
            }

            // EVIDENCE: did the team set a real standard and test the pessimistic case?
            var evidenceScore = 40;
            if (ds.evidence === 'independent') evidenceScore += 18;
            else if (ds.evidence === 'longterm') evidenceScore += 24;
            if (ds.qalycase === 'pessim') evidenceScore += 22;
            else if (ds.qalycase === 'range') evidenceScore += 14;
            else if (ds.qalycase === 'face') evidenceScore -= 18; // swallowed the dossier
            // approving at face value when the pessimistic ICER would breach the threshold
            if (ds.qalycase === 'face' && treated > 0 && (incCost / (qPer * C.pessimMult)) > wtp) evidenceScore -= 12;

            // GOVERNANCE: held the framework under pressure / used managed access wisely.
            var governScore = 55;
            if (ds.recommendation === 'managed') governScore += 14; // middle path under uncertainty
            if (ds.recommendation === 'reject' && ds.qalycase !== 'pessim') governScore -= 8; // refused without managing
            if (ds.chief === 'hold') governScore += 16;
            else if (ds.chief === 'retier') governScore += 8;
            else if (ds.chief === 'cave') governScore -= 24; // abandoned the framework under pressure
            if (ds.discount === 'outcomes') governScore += 10; // tied price to value
            else if (ds.discount === 'reject' && ds.recommendation !== 'reject') governScore -= 4;
            if (ds.equity === 'ced') governScore += 8;
            else if (ds.equity === 'open' && burden > 1.0) governScore -= 12;

            // Persist sub-scores (use the round's relevant ones; carry others forward)
            state.domainState.valueScore = this._clamp(valueScore);
            state.domainState.affordScore = this._clamp(affordScore);
            state.domainState.evidenceScore = this._clamp(evidenceScore);
            state.domainState.governScore = this._clamp(governScore);

            // Composite defensibility — weighting reflects the concept's pedagogy.
            var defens = Math.round(
                0.30 * state.domainState.valueScore +
                0.28 * state.domainState.affordScore +
                0.22 * state.domainState.evidenceScore +
                0.20 * state.domainState.governScore
            );
            state.domainState.defensibility = this._clamp(defens);

            // ---- history for chart ----
            state.domainState.icerHistory.push(Math.min(80000, icer));
            state.domainState.regBudgetHistory.push(Math.round(regBudget / 100000) / 10);
            state.domainState.defensHistory.push(state.domainState.defensibility);
            state.domainState.wtpHistory.push(Math.round(wtp / 1000));

            // ---- decision labels for log ----
            var roundChoices = [];
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                var chosen = ds[d.id];
                var optLabel;
                if (d.type === 'range') {
                    optLabel = this._fmtRange(d, chosen, t);
                } else {
                    optLabel = chosen;
                    for (var j = 0; j < d.options.length; j++) {
                        if (d.options[j].value === chosen) { optLabel = t(d.options[j].labelKey); break; }
                    }
                }
                roundChoices.push({ label: t(d.labelKey), value: optLabel });
            }
            state.domainState.decisionsLog.push({ round: idx + 1, choices: roundChoices });

            var feedback = this._buildFeedback(idx, state, { icer: icer, wtp: wtp, regBudget: regBudget, treated: treated, qPer: qPer });

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
                self._showFeedback(idx, feedback);
                self._refreshMeters();
            }, 350);

            // v1.1.0 FIX A — surface the already-computed headline metric on the
            // reporting-layer paths (express_resolveDomainScore reads performance.overallScore
            // or top-level domainState.score; the trend chart reads results.score/overallScore).
            var _hs = Math.round(state.domainState.defensibility);
            var _gk = _hs >= 80 ? 'grade_exemplary' : _hs >= 65 ? 'grade_competent' : _hs >= 45 ? 'grade_developing' : 'grade_beginner';
            state.domainState.score = _hs;
            state.domainState.performance = { overallScore: _hs, grade: t(_gk) };
            return {
                period: state.currentPeriod,
                score: _hs,
                overallScore: _hs,
                phase: t(round.phaseKey),
                roundLabel: t(round.titleKey),
                icer: icer,
                wtp: wtp,
                hospBudget: Math.round(hospBudget),
                regBudget: Math.round(regBudget),
                qalys: Math.round(qalysGained),
                treated: treated,
                accessPct: accessPct,
                value: state.domainState.valueScore,
                afford: state.domainState.affordScore,
                evidence: state.domainState.evidenceScore,
                govern: state.domainState.governScore,
                defensibility: state.domainState.defensibility,
                feedback: feedback
            };
        }

        // ===================== FEEDBACK =====================
        _buildFeedback(idx, state, m) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var d = state.decisions;
            var fb = '';
            if (idx === 0) {
                if (d.qalycase === 'face') fb = t('fb_r1_face');
                else if ((d.qalycase === 'pessim' || d.qalycase === 'range') && (d.evidence === 'independent' || d.evidence === 'longterm')) fb = t('fb_r1_strong');
                else fb = t('fb_r1_mixed');
            } else if (idx === 1) {
                if (d.subgroup === 'all') fb = t('fb_r2_all');
                else if (m.regBudget > this.C.regionAbsorbable * 1.3) fb = t('fb_r2_budget');
                else if (d.subgroup === 'advanced') fb = t('fb_r2_targeted');
                else fb = t('fb_r2_mixed');
            } else if (idx === 2) {
                if (d.recommendation === 'adopt' && d.tier === 'full') fb = t('fb_r3_blanket');
                else if (d.recommendation === 'reject') fb = t('fb_r3_reject');
                else if (d.recommendation === 'managed' || d.tier === 'outcomes' || d.tier === 'capped') fb = t('fb_r3_managed');
                else fb = t('fb_r3_mixed');
            } else {
                if (d.chief === 'cave') fb = t('fb_r4_cave');
                else if (d.chief === 'hold' && d.discount === 'outcomes') fb = t('fb_r4_strong');
                else if (d.discount === 'reject' && d.equity === 'open') fb = t('fb_r4_inconsistent');
                else fb = t('fb_r4_mixed');
            }
            return fb;
        }

        _showFeedback(idx, text) {
            var panel = document.getElementById('feedbackPanel');
            var titleEl = document.getElementById('feedbackTitle');
            var textEl = document.getElementById('feedbackText');
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (panel && textEl) {
                if (titleEl) titleEl.textContent = t('feedback_title') + ' — ' + t(this.ROUNDS[idx].titleKey);
                textEl.innerHTML = text;
                panel.style.display = 'block';
            }
        }

        // ===================== UI BINDING =====================
        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('icerDisplay', 'domainState.icer', function(v) { return self._fmtMoney(v); });
            uiManager.bind('hospBudgetDisplay', 'domainState.hospBudget', function(v) { return self._fmtM(v); });
            uiManager.bind('regBudgetDisplay', 'domainState.regBudget', function(v) { return self._fmtM(v); });
            uiManager.bind('qalyDisplay', 'domainState.qalysGained', function(v) { return Math.round(v); });
            uiManager.bind('accessDisplay', 'domainState.accessPct', function(v) { return Math.round(v) + '%'; });
            uiManager.bind('scoreDisplay', 'domainState.defensibility', function(v) { return Math.round(v); });

            setTimeout(function() {
                if (window.mySimulation && window.mySimulation.uiManager) {
                    var ui = window.mySimulation.uiManager;
                    var origUpdate = ui.updateBindings;
                    if (origUpdate && !ui.__htaPatched) {
                        ui.__htaPatched = true;
                        ui.updateBindings = function() {
                            origUpdate.apply(ui, arguments);
                            self._refreshMeters();
                        };
                    }
                    self._refreshMeters();
                }
            }, 120);
        }

        _refreshMeters() {
            var s = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null;
            if (!s) return;

            // hospital budget meter (relative to envelope, capped at 100%+)
            var hospEl = document.getElementById('hospBudgetMeter');
            if (hospEl) {
                var hp = Math.max(0, Math.min(140, (s.hospBudget / this.C.envelope) * 100));
                hospEl.style.width = Math.min(100, hp) + '%';
                hospEl.style.background = hp > 100 ? 'linear-gradient(90deg,#d64545,#e8804a)'
                    : hp > 80 ? 'linear-gradient(90deg,#e0a83e,#e8c14a)'
                    : 'linear-gradient(90deg,#11998e,#1a8fb5)';
            }
            // access meter
            var accEl = document.getElementById('accessMeter');
            if (accEl) {
                var ap = Math.max(0, Math.min(100, s.accessPct));
                accEl.style.width = ap + '%';
                accEl.style.background = 'linear-gradient(90deg,#1a8fb5,#11998e)';
            }
            // defensibility score meter
            var scEl = document.getElementById('scoreMeter');
            if (scEl) {
                var sc = Math.max(0, Math.min(100, s.defensibility));
                scEl.style.width = sc + '%';
                scEl.style.background = sc < 40 ? 'linear-gradient(90deg,#d64545,#e8804a)'
                    : sc < 65 ? 'linear-gradient(90deg,#e0a83e,#e8c14a)'
                    : 'linear-gradient(90deg,#1f9d6b,#11998e)';
            }
            // ICER card colour vs WTP
            var icerCard = document.querySelector('.hta-sim-kpi-icer');
            if (icerCard) {
                icerCard.classList.remove('hta-sim-over', 'hta-sim-under');
                if (s.icer > (s.wtp || 34000)) icerCard.classList.add('hta-sim-over');
                else if (s.icer > 0) icerCard.classList.add('hta-sim-under');
            }
        }

        // ===================== CHART =====================
