                        datasets: [
                            { label: 'ICER (€/QALY, k)', data: [], borderColor: '#1a8fb5', backgroundColor: 'rgba(26,143,181,0.08)', borderWidth: 2, tension: 0.25, pointRadius: 4, yAxisID: 'y' },
                            { label: 'WTP threshold (€/QALY, k)', data: [], borderColor: '#9aa7b0', borderDash: [6, 4], borderWidth: 2, tension: 0, pointRadius: 0, yAxisID: 'y' },
                            { label: 'Regional budget impact (€M)', data: [], borderColor: '#d64545', backgroundColor: 'rgba(214,69,69,0.06)', borderWidth: 2, tension: 0.25, pointRadius: 4, yAxisID: 'y1' },
                            { label: 'Defensibility score', data: [], borderColor: '#1f9d6b', backgroundColor: 'rgba(31,157,107,0.06)', borderWidth: 2, tension: 0.25, pointRadius: 4, yAxisID: 'y2' }
