        getChartData(state) {
            var labels = state.domainState.defensHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                htaChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.icerHistory },
                        { data: state.domainState.wtpHistory },
                        { data: state.domainState.regBudgetHistory },
                        { data: state.domainState.defensHistory }
                    ]
                }
            };
        }

        // ===================== HINTS =====================
        getHint(state, results) {
            if (!results) return null;
            if (results.icer > results.wtp) return window.mySimulation.t('hint_icer_over');
            if (results.regBudget > this.C.regionAbsorbable * 1.3) return window.mySimulation.t('hint_budget_high');
            if (results.evidence < 45) return window.mySimulation.t('hint_evidence_weak');
            if (results.treated === 0) return window.mySimulation.t('hint_rejected');
            if (results.govern < 45) return window.mySimulation.t('hint_govern_weak');
            if (results.defensibility >= 75) return window.mySimulation.t('hint_strong');
            return window.mySimulation.t('hint_default');
        }

        // ===================== HISTORY TABLE =====================
        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.phase', label: 'Phase', i18nKey: 'col_phase' },
                { key: 'results.icer', label: 'ICER', i18nKey: 'col_icer', formatter: function(v) { return self._fmtMoney(v); } },
                { key: 'results.regBudget', label: 'Regional BIA', i18nKey: 'col_regbudget', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.qalys', label: 'QALYs', i18nKey: 'col_qalys', formatter: function(v) { return Math.round(v); } },
                { key: 'results.accessPct', label: 'Access', i18nKey: 'col_access', formatter: function(v) { return Math.round(v) + '%'; } },
                { key: 'results.defensibility', label: 'Defensibility', i18nKey: 'col_defens', formatter: function(v) { return Math.round(v); } }
            ];
        }

        getPresets() { return null; }

        // ===================== END-SCREEN SUMMARY =====================
        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? Math.round(summary.score) : 0;
            var metrics = summary.metrics || [];
            var msg = summary.message || '';
            var cells = metrics.map(function (m) {
                return '<div class="wtd-completion-metric"><span>' + m.label + '</span><strong>' + m.value + '</strong></div>';
            }).join('');
            return ''
                + '<div class="wtd-completion">'
                +   '<div class="wtd-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="wtd-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="wtd-completion-metrics">' + cells + '</div>'
                +   (msg ? '<div class="wtd-completion-verdict">' + msg + '</div>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var last = history[history.length - 1].results || {};
            var defens = last.defensibility || 0;

            var verdictKey;
            if (defens >= 80) verdictKey = 'summary_exemplary';
            else if (defens >= 65) verdictKey = 'summary_competent';
            else if (defens >= 45) verdictKey = 'summary_developing';
            else verdictKey = 'summary_beginner';

            return {
                score: defens,
                metrics: [
                    { label: t('sum_defensibility'), value: Math.round(defens) },
                    { label: t('sum_value'), value: Math.round(last.value || 0) },
                    { label: t('sum_afford'), value: Math.round(last.afford || 0) },
                    { label: t('sum_evidence'), value: Math.round(last.evidence || 0) },
                    { label: t('sum_govern'), value: Math.round(last.govern || 0) },
                    { label: t('sum_finalicer'), value: this._fmtMoney(last.icer || 0) },
                    { label: t('sum_regbudget'), value: this._fmtM(last.regBudget || 0) },
                    { label: t('sum_qalys'), value: Math.round(last.qalys || 0) }
                ],
                message: t(verdictKey)
            };
        }

        // ===================== TRANSLATIONS =====================
        getTranslations() {
            return {
                en: {
                    comp_heading: `Health-Technology Assessment — Committee Verdict`,
                    comp_score_label: `Defensibility`,
                    grade_exemplary: `Exemplary`,
                    grade_competent: `Competent`,
                    grade_developing: `Developing`,
                    grade_beginner: `Needs work`,
                    header_status: `HTA UNIT · AZIENDA OSPEDALIERA SAN GERARDO · LOMBARDY`,
                    title: `Worth the Device`,
                    subtitle: `VentriGuard market-access appraisal · €22,000/patient · devices envelope €2.4M`,
                    round_label: `Round`,
                    period_of: `of`,
                    kpi_icer: `ICER (cost per QALY)`,
                    kpi_icer_sub: `vs your WTP threshold`,
